//! A sorted set of at most 8 distinct `i64` values.

/// A set of at most 8 distinct values.
///
/// Invariant (every method may rely on it and must keep it): `len <= 8`, and
/// the values `items[0..len]` are strictly increasing.
#[derive(Clone, Debug)]
pub struct SortedSet {
    items: [i64; 8],
    len: usize,
}

impl SortedSet {
    pub fn new() -> SortedSet {
        SortedSet { items: [0; 8], len: 0 }
    }

    pub fn size(&self) -> usize {
        self.len
    }

    /// The `i`-th smallest value.
    pub fn at(&self, i: usize) -> Option<i64> {
        if i < self.len {
            Some(self.items[i])
        } else {
            None
        }
    }

    pub fn contains(&self, x: i64) -> bool {
        for i in 0..self.len {
            if self.items[i] == x {
                return true;
            }
            if self.items[i] > x {
                return false;
            }
        }
        false
    }

    /// Adds `x`; `false` (and no change) when `x` is there already or the
    /// set is full.
    pub fn insert(&mut self, x: i64) -> bool {
        if self.len == 8 {
            return false;
        }
        let mut p = 0;
        while p < self.len && self.items[p] < x {
            p += 1;
        }
        if p < self.len && self.items[p] == x {
            return false;
        }
        let mut j = self.len;
        while j > p {
            self.items[j] = self.items[j - 1];
            j -= 1;
        }
        self.items[p] = x;
        self.len += 1;
        true
    }

    /// Removes `x`; `false` when `x` is not there.
    pub fn remove(&mut self, x: i64) -> bool {
        let mut p = 0;
        while p < self.len && self.items[p] != x {
            p += 1;
        }
        if p == self.len {
            return false;
        }
        for j in p..self.len - 1 {
            self.items[j] = self.items[j + 1];
        }
        self.len -= 1;
        true
    }

    /// Replaces `from` with `to`: when `from` is in the set and `to` is not,
    /// removes `from` and inserts `to`, returning `true`; otherwise leaves
    /// the set unchanged and returns `false`.
    pub fn replace(&mut self, from: i64, to: i64) -> bool {
        if !self.contains(from) || self.contains(to) {
            return false;
        }
        self.remove(from);
        self.insert(to);
        true
    }
}

#[cfg(test)]
mod tests {
    use super::SortedSet;

    fn values(s: &SortedSet) -> Vec<i64> {
        (0..s.size()).map(|i| s.at(i).unwrap()).collect()
    }

    /// Checks the documented invariant holds for the public view.
    fn check_invariant(s: &SortedSet) {
        assert!(s.size() <= 8);
        let v = values(s);
        assert!(v.windows(2).all(|w| w[0] < w[1]));
    }

    #[test]
    fn replace_moves_value() {
        let mut s = SortedSet::new();
        for x in [10, 20, 30] {
            s.insert(x);
        }
        assert!(s.replace(20, 15));
        assert_eq!(values(&s), vec![10, 15, 30]);
        check_invariant(&s);
    }

    #[test]
    fn replace_into_empty_and_at_edges() {
        let mut s = SortedSet::new();
        s.insert(0);
        assert!(s.replace(0, 100));
        assert_eq!(values(&s), vec![100]);
        check_invariant(&s);

        let mut s = SortedSet::new();
        for x in [1, 2, 3] {
            s.insert(x);
        }
        assert!(s.replace(1, 0));
        assert_eq!(values(&s), vec![0, 2, 3]);
        assert!(s.replace(3, 4));
        assert_eq!(values(&s), vec![0, 2, 4]);
        check_invariant(&s);
    }

    #[test]
    fn replace_full_set_stays_full() {
        let mut s = SortedSet::new();
        for x in 1..=8 {
            s.insert(x);
        }
        assert!(s.replace(5, 9));
        assert_eq!(values(&s), vec![1, 2, 3, 4, 6, 7, 8, 9]);
        check_invariant(&s);
        assert!(s.replace(9, 0));
        assert_eq!(values(&s), vec![0, 1, 2, 3, 4, 6, 7, 8]);
        check_invariant(&s);
    }

    #[test]
    fn replace_noop_cases() {
        let mut s = SortedSet::new();
        for x in [1, 2, 3] {
            s.insert(x);
        }
        // `from` not in the set.
        assert!(!s.replace(4, 10));
        // `to` already in the set.
        assert!(!s.replace(1, 3));
        // `from == to` (present).
        assert!(!s.replace(2, 2));
        assert_eq!(values(&s), vec![1, 2, 3]);
        check_invariant(&s);
    }

    #[test]
    fn replace_on_empty() {
        let s = &mut SortedSet::new();
        assert!(!s.replace(1, 2));
        assert_eq!(s.size(), 0);
        check_invariant(s);
    }

    #[test]
    fn replace_extreme_values() {
        let mut s = SortedSet::new();
        s.insert(i64::MIN);
        s.insert(i64::MAX);
        assert!(!s.replace(i64::MIN, i64::MAX));
        assert!(s.replace(i64::MAX, 0));
        assert_eq!(values(&s), vec![i64::MIN, 0]);
        check_invariant(&s);
    }
}

