use proptest::prelude::*;
use solution::SortedSet;
use std::collections::BTreeSet;

fn values(s: &SortedSet) -> Vec<i64> {
    (0..s.size()).map(|i| s.at(i).unwrap()).collect()
}

fn model_replace(model: &mut BTreeSet<i64>, from: i64, to: i64) -> bool {
    let ok = model.contains(&from) && !model.contains(&to);
    if ok {
        model.remove(&from);
        model.insert(to);
    }
    ok
}

proptest! {
    #[test]
    fn replace_matches_model(seq in proptest::collection::vec(any::<i64>(), 0..=30)) {
        let mut s = SortedSet::new();
        let mut model: BTreeSet<i64> = BTreeSet::new();

        let mut i = 0;
        while i + 3 <= seq.len() {
            let op = seq[i] % 3;
            let a = seq[i + 1];
            let b = seq[i + 2];
            i += 3;

            let expected = match op {
                0 => model.insert(a),
                1 => model.remove(&a),
                _ => model_replace(&mut model, a, b),
            };
            let actual = match op {
                0 => s.insert(a),
                1 => s.remove(a),
                _ => s.replace(a, b),
            };
            assert_eq!(actual, expected, "op {op}(from={a}, to={b}) disagreed");
            assert_eq!(s.size(), model.len());
            assert_eq!(values(&s), model.iter().copied().collect::<Vec<_>>());
        }
    }

    #[test]
    fn replace_random(from in any::<i64>(), to in any::<i64>(),
                      base in proptest::collection::vec(any::<i64>(), 0..=8)) {
        let mut s = SortedSet::new();
        let mut model: BTreeSet<i64> = BTreeSet::new();
        for x in base {
            s.insert(x);
            model.insert(x);
        }
        let expected = model_replace(&mut model, from, to);
        let actual = s.replace(from, to);
        assert_eq!(actual, expected);
        assert_eq!(values(&s), model.iter().copied().collect::<Vec<_>>());
    }
}

