use std::collections::VecDeque;

use proptest::prelude::*;
use solution::Ring;

fn contents(r: &Ring) -> Vec<i64> {
    (0..r.size()).map(|i| r.get(i).unwrap()).collect()
}

#[test]
fn overwrite_none_until_full() {
    let mut r = Ring::new();
    for x in 0..8 {
        assert_eq!(r.push_overwrite(x), None, "not full yet: x={x}");
        assert_eq!(r.size(), (x + 1) as usize);
    }
    assert_eq!(contents(&r), vec![0, 1, 2, 3, 4, 5, 6, 7]);
}

#[test]
fn overwrite_full_drops_oldest_and_keeps_newest() {
    let mut r = Ring::new();
    for x in 0..8 {
        r.push(x);
    }
    // 8 overwrites: the original oldest 0..7 are dropped one by one.
    for (old, new) in (0..8).zip(16..24) {
        assert_eq!(r.push_overwrite(new), Some(old));
        assert_eq!(r.size(), 8);
    }
    assert_eq!(contents(&r), vec![16, 17, 18, 19, 20, 21, 22, 23]);
    assert_eq!(r.get(7), Some(23), "newest is at the back");

    // keep going so the dropped values keep advancing
    assert_eq!(r.push_overwrite(24), Some(16));
    assert_eq!(r.push_overwrite(25), Some(17));
    assert_eq!(contents(&r), vec![18, 19, 20, 21, 22, 23, 24, 25]);
}

#[test]
fn overwrite_works_when_head_is_not_zero() {
    let mut r = Ring::new();
    for x in 0..8 {
        assert!(r.push(x));
    }
    for x in 0..5 {
        assert_eq!(r.pop(), Some(x)); // head is now 5
    }
    for x in 8..13 {
        assert!(r.push(x));
    }
    assert_eq!(contents(&r), vec![5, 6, 7, 8, 9, 10, 11, 12]);

    assert_eq!(r.push_overwrite(99), Some(5)); // head 5 -> 6
    assert_eq!(contents(&r), vec![6, 7, 8, 9, 10, 11, 12, 99]);

    assert_eq!(r.push_overwrite(98), Some(6)); // head 6 -> 7
    assert_eq!(contents(&r), vec![7, 8, 9, 10, 11, 12, 99, 98]);

    assert_eq!(r.push_overwrite(97), Some(7)); // head 7 -> 0 (wrap)
    assert_eq!(contents(&r), vec![8, 9, 10, 11, 12, 99, 98, 97]);

    assert_eq!(r.push_overwrite(96), Some(8)); // head 0 -> 1
    assert_eq!(contents(&r), vec![9, 10, 11, 12, 99, 98, 97, 96]);
}

#[test]
fn overwrite_after_popping_to_empty_and_refilling() {
    let mut r = Ring::new();
    for x in 0..8 {
        r.push(x);
    }
    for x in 0..8 {
        assert_eq!(r.pop(), Some(x));
    }
    // head is back at 0, len 0: overwrite behaves like a plain push.
    for x in 100..108 {
        assert_eq!(r.push_overwrite(x), None);
    }
    assert_eq!(r.size(), 8);
    assert_eq!(contents(&r), vec![100, 101, 102, 103, 104, 105, 106, 107]);
    assert_eq!(r.push_overwrite(111), Some(100));
    assert_eq!(contents(&r), vec![101, 102, 103, 104, 105, 106, 107, 111]);
}

#[test]
fn mixed_sequence() {
    let mut r = Ring::new();
    // fill up to 8 with a mix of the two insertion methods
    assert_eq!(r.push_overwrite(1), None);
    assert!(r.push(2));
    assert_eq!(r.push_overwrite(3), None);
    assert_eq!(r.push_overwrite(4), None);
    assert!(r.push(5));
    assert_eq!(r.push_overwrite(6), None);
    assert!(r.push(7));
    assert!(r.push(8));
    assert_eq!(r.size(), 8);
    assert!(!r.push(100), "plain push still refuses when full");
    assert_eq!(contents(&r), vec![1, 2, 3, 4, 5, 6, 7, 8]);
    assert_eq!(r.push_overwrite(9), Some(1));
    assert_eq!(contents(&r), vec![2, 3, 4, 5, 6, 7, 8, 9]);
    assert_eq!(r.push_overwrite(10), Some(2));
    assert_eq!(r.pop(), Some(3));
    assert_eq!(r.push_overwrite(11), None); // not full any more
    assert_eq!(contents(&r), vec![4, 5, 6, 7, 8, 9, 10, 11]);
}

proptest! {
    #[test]
    fn matches_shadow_model(
        ops in prop::collection::vec(
            prop_oneof![
                any::<i64>().prop_map(|x| ("ow".to_string(), x)),
                any::<i64>().prop_map(|x| ("push".to_string(), x)),
                (0..1).prop_map(|_| ("pop".to_string(), 0)),
            ],
            0..300,
        ),
    ) {
        let mut r = Ring::new();
        let mut m: VecDeque<i64> = VecDeque::new();
        for (kind, x) in ops {
            match kind.as_str() {
                "ow" => {
                    let exp = if m.len() == 8 { m.pop_front() } else { None };
                    assert_eq!(r.push_overwrite(x), exp);
                    m.push_back(x);
                }
                "push" => {
                    let fits = m.len() < 8;
                    assert_eq!(r.push(x), fits);
                    if fits {
                        m.push_back(x);
                    }
                }
                "pop" => {
                    assert_eq!(r.pop(), m.pop_front());
                }
                _ => unreachable!(),
            }
            // The whole content, oldest first, must agree after every step.
            assert_eq!(r.size(), m.len());
            for i in 0..8usize {
                assert_eq!(r.get(i), m.get(i).copied());
            }
        }
    }
}

