//! A set of `i64` values stored as at most 8 intervals.

/// The values `lo[i]..=hi[i]` for `i < len`.
///
/// Invariant (every method may rely on it and must keep it): `len <= 8`;
/// every span is nonempty (`lo[i] <= hi[i]`); the spans are in increasing
/// order and two neighbours never touch: `hi[i] + 1 < lo[i + 1]` (there is
/// at least one value between them). So each set of values has exactly one
/// list.
#[derive(Clone, Debug)]
pub struct Spans {
    lo: [i64; 8],
    hi: [i64; 8],
    len: usize,
}

impl Spans {
    pub fn new() -> Spans {
        Spans { lo: [0; 8], hi: [0; 8], len: 0 }
    }

    pub fn count(&self) -> usize {
        self.len
    }

    /// The first value of the `i`-th span.
    pub fn first(&self, i: usize) -> Option<i64> {
        if i < self.len {
            Some(self.lo[i])
        } else {
            None
        }
    }

    /// The last value of the `i`-th span.
    pub fn last(&self, i: usize) -> Option<i64> {
        if i < self.len {
            Some(self.hi[i])
        } else {
            None
        }
    }

    pub fn contains(&self, x: i64) -> bool {
        for i in 0..self.len {
            if x < self.lo[i] {
                return false;
            }
            if x <= self.hi[i] {
                return true;
            }
        }
        false
    }

    /// Appends the span `lo..=hi` after the last one. `false` (and no
    /// change) when `lo > hi`, when the span does not lie above the last one
    /// with a gap, or when the list is full.
    pub fn push(&mut self, lo: i64, hi: i64) -> bool {
        if lo > hi || self.len == 8 {
            return false;
        }
        if self.len > 0 && (self.hi[self.len - 1] >= lo || self.hi[self.len - 1] + 1 == lo) {
            return false;
        }
        self.lo[self.len] = lo;
        self.hi[self.len] = hi;
        self.len += 1;
        true
    }

    /// Takes the single value `x` out of the set and returns `true`.
    ///
    /// A span that holds only `x` disappears, `x` at either end of a span
    /// shortens it, and `x` inside a span splits it in two. A split needs a
    /// free place: when the list already has 8 spans, it is left unchanged
    /// and `false` is returned. When `x` is not in the set, `false` is
    /// returned and the list is left unchanged.
    pub fn remove(&mut self, x: i64) -> bool {
        for i in 0..self.len {
            if x < self.lo[i] {
                return false;
            }
            if x > self.hi[i] {
                continue;
            }
            if x == self.lo[i] && x == self.hi[i] {
                // Span holds only x: drop it and shift the rest left.
                self.lo.copy_within(i + 1..self.len, i);
                self.hi.copy_within(i + 1..self.len, i);
                self.len -= 1;
            } else if x == self.lo[i] {
                // x < hi[i] here, so x + 1 cannot overflow.
                self.lo[i] = x + 1;
            } else if x == self.hi[i] {
                // x > lo[i] here, so x - 1 cannot overflow.
                self.hi[i] = x - 1;
            } else {
                // lo[i] < x < hi[i]: split into two; needs a free slot.
                if self.len == 8 {
                    return false;
                }
                self.lo.copy_within(i..self.len, i + 1);
                self.hi.copy_within(i..self.len, i + 1);
                self.hi[i] = x - 1;
                self.lo[i + 1] = x + 1;
                self.len += 1;
            }
            return true;
        }
        false
    }
}

