use proptest::prelude::*;
use solution::Spans;
use std::collections::BTreeSet;

fn spans(s: &Spans) -> Vec<(i64, i64)> {
    (0..s.count()).map(|i| (s.first(i).unwrap(), s.last(i).unwrap())).collect()
}

/// Check the documented invariant on a live `Spans`, cross-referencing the
/// independent model `list`.
fn check_invariants(s: &Spans, list: &[(i64, i64)]) {
    assert!(s.count() <= 8);
    assert_eq!(spans(s), list);
    for &(l, h) in list {
        assert!(l <= h);
    }
    for w in 0..list.len().saturating_sub(1) {
        let (_, h1) = list[w];
        let (l2, _) = list[w + 1];
        assert!(h1 + 1 < l2); // gap of at least one value; safe for bounded values
    }
}

/// Canonical span list of a set of values (independent model).
fn canonical(set: &BTreeSet<i64>) -> Vec<(i64, i64)> {
    let mut v = Vec::new();
    let mut it = set.iter().copied();
    if let Some(start) = it.next() {
        let (mut s0, mut prev) = (start, start);
        for val in it {
            if val == prev + 1 {
                prev = val;
            } else {
                v.push((s0, prev));
                (s0, prev) = (val, val);
            }
        }
        v.push((s0, prev));
    }
    v
}

/// Would `push(lo, hi)` succeed on `list`? (mirrors Spans::push rules)
fn model_push_ok(list: &[(i64, i64)], lo: i64, hi: i64) -> bool {
    if lo > hi || list.len() == 8 {
        return false;
    }
    if let Some(&(_, h)) = list.last() {
        if h >= lo {
            return false; // overlap
        }
        if h + 1 == lo {
            return false; // touching; safe here since h < lo
        }
    }
    true
}

/// Would `remove(x)` succeed on `list`?
fn model_remove_ok(list: &[(i64, i64)], x: i64) -> bool {
    match list.iter().position(|&(l, h)| x >= l && x <= h) {
        None => false,
        Some(i) => {
            let (l, h) = list[i];
            if l == h || x == l || x == h {
                true
            } else {
                list.len() < 8 // split needs a free place
            }
        }
    }
}

#[derive(Debug, Clone)]
enum Op {
    Push(i64, i64),
    Remove(i64),
    Contains(i64),
}

fn op() -> impl Strategy<Value = Op> {
    (any::<u32>(), any::<i64>(), any::<i64>())
        .prop_map(|(kind, a, b)| match kind % 3 {
            0 => Op::Push(a.clamp(-1000, 1000), b.clamp(-1000, 1000)),
            1 => Op::Remove(a.clamp(-1010, 1010)),
            _ => Op::Contains(b.clamp(-1010, 1010)),
        })
}

proptest! {
    #[test]
    fn random_ops_match_model(ops in prop::collection::vec(op(), 0..300)) {
        let mut s = Spans::new();
        let mut set: BTreeSet<i64> = BTreeSet::new();
        let mut list: Vec<(i64, i64)> = Vec::new();

        for op in ops {
            match op {
                Op::Push(lo, hi) => {
                    let want = model_push_ok(&list, lo, hi);
                    let got = s.push(lo, hi);
                    assert_eq!(got, want, "push({lo},{hi})");
                    if want {
                        set.extend(lo..=hi);
                    }
                    list = canonical(&set);
                    check_invariants(&s, &list);
                }
                Op::Remove(x) => {
                    let want = model_remove_ok(&list, x);
                    let got = s.remove(x);
                    assert_eq!(got, want, "remove({x})");
                    if want {
                        assert!(set.remove(&x));
                        list = canonical(&set);
                    }
                    check_invariants(&s, &list);
                }
                Op::Contains(x) => {
                    assert_eq!(s.contains(x), set.contains(&x), "contains({x})");
                }
            }
        }
    }
}

