fn remove_split_needs_free_place() {
    let mut s = Spans::new();
    // 8 full spans, each 5 wide: [0..4],[10..14],...
    for i in 0..8 {
        assert!(s.push(10 * i, 10 * i + 4));
    }
    let before = spans(&s);
    // x strictly inside a span -> would need 9 spans
    for x in [2, 12, 72] {
        assert!(!s.remove(x), "x={x}");
    }
    // x absent -> false too
    assert!(!s.remove(5));
    // list untouched
    assert_eq!(spans(&s), before);
    assert_eq!(s.count(), 8);
    // but removing an end of a span is still fine (no new span needed)
    assert!(s.remove(4));
    assert_eq!(
        spans(&s),
        vec![(0, 3), (10, 14), (20, 24), (30, 34), (40, 44), (50, 54), (60, 64), (70, 74)]
    );
    // and removing a whole singleton span is fine even at 8
    let mut t = Spans::new();
    for i in 0..8 {
        assert!(t.push(2 * i, 2 * i)); // set {0, 2, ..., 14}
    }
    assert!(t.remove(6));
    assert_eq!(
        spans(&t),
        vec![(0, 0), (2, 2), (4, 4), (8, 8), (10, 10), (12, 12), (14, 14)]
    );
}

#[test]
fn remove_extreme_values() {
    let mut s = Spans::new();
    s.push(i64::MIN, i64::MIN + 3);
    s.push(i64::MAX - 3, i64::MAX);
    assert!(s.remove(i64::MIN));
    assert_eq!(s.first(0), Some(i64::MIN + 1));
    assert!(s.remove(i64::MAX));
    assert_eq!(s.last(1), Some(i64::MAX - 1));
    // full-range span: splitting and shrinking must not overflow
    let mut t = Spans::new();
    t.push(i64::MIN, i64::MAX);
    assert!(t.remove(1));
    assert_eq!(t.first(0), Some(i64::MIN));
    assert_eq!(t.last(0), Some(0));
    assert_eq!(t.first(1), Some(2));
    assert_eq!(t.last(1), Some(i64::MAX));
    assert!(t.remove(i64::MAX - 1));
    assert_eq!(
        spans(&t),
        vec![(i64::MIN, 0), (2, i64::MAX - 2), (i64::MAX, i64::MAX)]
    );
    assert!(t.remove(i64::MAX - 2));
    assert_eq!(
        spans(&t),
        vec![(i64::MIN, 0), (2, i64::MAX - 3), (i64::MAX, i64::MAX)]
    );
    // singleton extremes
    let mut u = Spans::new();
    u.push(i64::MIN, i64::MIN);
    assert!(u.remove(i64::MIN));
    assert_eq!(u.count(), 0);
    u.push(i64::MAX, i64::MAX);
    assert!(u.remove(i64::MAX));
    assert_eq!(u.count(), 0);
}

