//! A binary min-heap of at most 8 `i64` values.

/// The values `a[0..len]` in heap order.
///
/// Invariant (every method may rely on it and must keep it): `len <= 8`,
/// and no value is smaller than its parent's: `a[(i - 1) / 2] <= a[i]` for
/// `0 < i < len`. So `a[0]` is the smallest.
#[derive(Clone, Debug)]
pub struct Heap {
    a: [i64; 8],
    len: usize,
}

impl Heap {
    pub fn new() -> Heap {
        Heap { a: [0; 8], len: 0 }
    }

    pub fn size(&self) -> usize {
        self.len
    }

    /// The smallest value.
    pub fn peek(&self) -> Option<i64> {
        if self.len == 0 {
            None
        } else {
            Some(self.a[0])
        }
    }

    /// Adds `x`; `false` when full: the value is not stored.
    pub fn push(&mut self, x: i64) -> bool {
        if self.len == 8 {
            return false;
        }
        let mut k = self.len;
        self.a[k] = x;
        self.len += 1;
        while k > 0 && self.a[(k - 1) / 2] > self.a[k] {
            let p = (k - 1) / 2;
            self.a.swap(p, k);
            k = p;
        }
        true
    }

    /// Removes the smallest value and returns it; `None` when the heap is empty.
    pub fn pop(&mut self) -> Option<i64> {
        if self.len == 0 {
            return None;
        }
        let top = self.a[0];
        // Replace the root with the last element, then shrink.
        self.a[0] = self.a[self.len - 1];
        self.len -= 1;
        // Sift the new root down: keep swapping with the smaller child.
        let mut k = 0usize;
        loop {
            let l = 2 * k + 1;
            if l >= self.len {
                break;
            }
            let r = l + 1;
            let s = if r < self.len && self.a[r] < self.a[l] {
                r
            } else {
                l
            };
            if self.a[k] <= self.a[s] {
                break;
            }
            self.a.swap(k, s);
            k = s;
        }
        Some(top)
    }
}

#[cfg(test)]
mod tests {
    use super::Heap;

    /// Direct check of the documented invariant on the private fields.
    fn check_invariant(h: &Heap) {
        assert!(h.len <= 8, "len out of bounds: {}", h.len);
        for i in 1..h.len {
            assert!(
                h.a[(i - 1) / 2] <= h.a[i],
                "heap order violated at i={} ({} > {})",
                i,
                h.a[(i - 1) / 2],
                h.a[i]
            );
        }
    }

    #[test]
    fn pop_empty_is_none() {
        let mut h = Heap::new();
        assert_eq!(h.pop(), None);
        assert_eq!(h.pop(), None);
        assert_eq!(h.size(), 0);
        check_invariant(&h);
    }

    #[test]
    fn pop_returns_values_in_sorted_order() {
        let mut h = Heap::new();
        for x in [5, 3, 8, 1, 9] {
            assert!(h.push(x));
        }
        for expected in [1, 3, 5, 8, 9] {
            assert_eq!(h.pop(), Some(expected));
            check_invariant(&h);
        }
        assert_eq!(h.pop(), None);
        assert_eq!(h.size(), 0);
        check_invariant(&h);
    }

    #[test]
    fn pop_from_full_heap() {
        let mut h = Heap::new();
        for x in [4, 2, 7, 1, 8, 3, 6, 5] {
            assert!(h.push(x));
        }
        let mut got = Vec::new();
        for _ in 0..8 {
            got.push(h.pop().unwrap());
            check_invariant(&h);
        }
        assert_eq!(got, [1, 2, 3, 4, 5, 6, 7, 8]);
        assert_eq!(h.pop(), None);
    }

    #[test]
    fn pop_with_duplicates() {
        let mut h = Heap::new();
        for x in [2, 2, 1, 2, 0, 1, 1, 3] {
            assert!(h.push(x));
        }
        let got: Vec<i64> = (0..8).map(|_| h.pop().unwrap()).collect();
        assert_eq!(got, [0, 1, 1, 1, 2, 2, 2, 3]);
    }

    #[test]
    fn pop_extreme_values() {
        let mut h = Heap::new();
        assert!(h.push(i64::MAX));
        assert!(h.push(i64::MIN));
        assert_eq!(h.pop(), Some(i64::MIN));
        assert_eq!(h.pop(), Some(i64::MAX));
        assert_eq!(h.pop(), None);
    }

    #[test]
    fn pop_single_element() {
        let mut h = Heap::new();
        assert!(h.push(-42));
        assert_eq!(h.pop(), Some(-42));
        assert_eq!(h.size(), 0);
        check_invariant(&h);
        // The heap is reusable afterwards.
        assert!(h.push(7));
        assert_eq!(h.pop(), Some(7));
    }

    #[test]
    fn peek_agrees_with_pop() {
        let mut h = Heap::new();
        for x in [9, 1, 7, 3, 5, 2, 8, 4] {
            assert!(h.push(x));
        }
        for _ in 0..8 {
            // The value popped is exactly the one peek reported before the pop.
            let next = h.peek();
            assert_eq!(h.pop(), next);
            check_invariant(&h);
        }
        assert_eq!(h.peek(), None);
        assert_eq!(h.pop(), None);
    }

    use proptest::prelude::*;

    #[derive(Clone, Copy, Debug)]
    enum Op {
        Push(i64),
        Pop,
    }

    fn op_arb() -> impl Strategy<Value = Op> {
        prop_oneof![
            any::<i64>().prop_map(Op::Push),
            (0i64..20).prop_map(Op::Push), // small range: many duplicates
            any::<bool>().prop_map(|_| Op::Pop),
        ]
    }

    proptest! {
        #[test]
        fn pop_matches_model(ops in prop::collection::vec(op_arb(), 0..40)) {
            let mut h = Heap::new();
            let mut model: Vec<i64> = Vec::new();

            for op in ops {
                match op {
                    Op::Push(x) => {
                        if model.len() < 8 {
                            assert!(h.push(x));
                            model.push(x);
                        } else {
                            assert!(!h.push(x));
                        }
                    }
                    Op::Pop => {
                        let expected = if model.is_empty() {
                            None
                        } else {
                            let m = *model.iter().min().unwrap();
                            let idx = model.iter().position(|&v| v == m).unwrap();
                            model.remove(idx);
                            Some(m)
                        };
                        assert_eq!(h.pop(), expected);
                    }
                }
                check_invariant(&h);
                assert_eq!(h.size(), model.len());
                assert_eq!(h.peek(), model.iter().min().copied());
            }

            // Draining must yield exactly the remaining values, sorted.
            let mut rest: Vec<i64> = Vec::new();
            while let Some(v) = h.pop() {
                rest.push(v);
            }
            model.sort_unstable();
            assert_eq!(rest, model);
            assert_eq!(h.size(), 0);
            check_invariant(&h);
        }
    }
}

